171	\section{The Magic Square game}
172	% Paper label sec:ms kept for cross-reference fidelity.
173	\label{sec:ms}
174	
175	We recall the Magic Square game of Mermin and Peres. It is a simple self-test for two EPR pairs, and it allows one to test that a pair of binary observables \emph{anticommutes}; both properties are used in the Pauli basis test. Here it is presented as a binary constraint satisfaction game. Throughout this section and the next, $\sigma^X$ and $\sigma^Z$ denote the single-qubit Pauli observables, with associated two-outcome projective measurements $\{\sigma^W_b\}_{b \in \F_2}$ for $W \in \{X,Z\}$.

      Taking the function $\delta_{\Line}$ in the lemma to be $\sqrt{\eps}$,
      this yields the conclusion of \Cref{eq:qld-comm-line-pt-cons2}
      of the lemma.
\end{proof}

 \subsection{Combining the $X$ and $Z$ measurements}
\label{sec:combining}

In this section our goal is to create a set of combined measurements
that simultaneously measure the approximately-commuting measurements
constructed in the previous section. We do this first for the points.
Recall that $\mH_\alice$ and $\mH_\bob$ denote the Hilbert spaces corresponding to
registers $\alice$ and $\bob$, respectively.

\begin{lemma}\label{lem:qld-4-10}
There exists a function $\delta_Q(\eps) = \poly(\eps)$ such that the following holds. 
	For every $x,z \in \F_q^m$ and $\mH \in \{ \mH_\alice, \mH_\bob\}$ there are projective measurements $\{ \hat{Q}^{x,z}_{a,b} \}_{a,b \in \F_q}$ acting on $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ such that:
	\begin{enumerate}
		\item (\textbf{Self-consistency}) On average over uniformly random $x,z \in \F_q^m$,
		\begin{equation}
			\label{eq:qld-q-self-cons}
			(\hat{Q}^{x,z}_{a,b})_{\alice \alice'}  \approx_{\delta_Q} (\hat{Q}^{x,z}_{a,b})_{\bob \alice''}\,.
		\end{equation}

		\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly random $x,z \in \F_q^m$,
		\begin{gather}
			\label{eq:qld-q-cons-m-hat-xz}
				(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,X),x}_{a} \hat{M}^{(\Point,Z),z}_b)_{\bob \alice''}\;, \\
							\label{eq:qld-q-cons-m-hat-zx}
				(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,Z),z}_b  \hat{M}^{(\Point,X),x}_{a} )_{\bob \alice''}\;.
		\end{gather}
              \end{enumerate}
                    Furthermore, all symmetric equivalents of these approximations
      also hold.
\end{lemma}

The construction of the measurements $\{ \hat{Q}^{x,z}_{a,b} \}$ whose existence is guaranteed in the lemma proceeds in three steps. In the first step, for every $(r,s)\in\F_q^2$ we combine the binary-outcome measurements $\hat{M}^{(\Point,X),x,r}_a$ and $\hat{M}^{(\Point,X),z,s}_b$; this is made possible by their approximate commutation as shown in Lemma~\ref{lem:qld-comm-cons}. In a second step, we show that the measurements thus constructed have a particular ``approximate linearity'' property, when seen as a function of the pair $(r,s)$. This allows us, in the third step, to combine them into a single measurement $\{ \hat{Q}^{x,z}_{a,b} \}$ with outcomes in $\F_q^2\cong \F_2^{2t}$ by applying the following  result from~\cite{NV17}:

	\begin{theorem}[Quantum linearity test]
	\label{thm:linearity}
		Let $0 \leq \delta \leq 1$, let $t$ be a positive integer, and let $\ket{\psi}$ be a state in a Hilbert space $\mathcal{H}_\alice \otimes \mathcal{H}_\bob$. Let $\{\mathcal{O}^u \}$ be a set of observables indexed by $u \in \F_2^t$ that act on $\mathcal{H}_\alice$. Suppose that on average over $u, u'$ chosen uniformly from $\F_2^t$, we have the following ``approximate linearity'' holds:
		\[
(\mathcal{O}^u \mathcal{O}^{u'})_{\alice} \approx_\delta (\mathcal{O}^{u+u'})_{\alice}
		\]
		where the $\approx$ statement is taken with respect to the state $\ket{\psi}$. 
Then there exists an extended state $\ket{\psi'}_{\alice \alice' \bob} = \ket{\psi}_{\alice \bob} \otimes \ket{0}_{\alice'}$ in an extended space $\mathcal{H}_{\alice} \otimes \mathcal{H}_\bob \otimes \mathcal{H}_{\alice'}$ and observables $\{ \mathcal{L}^u \}$ acting on $\mathcal{H}_\alice \otimes \mathcal{H}_{\alice'}$ such that for all $u, u' \in \F_2^t$, 
		\[
			\mathcal{L}^u \mathcal{L}^{u'} = \mathcal{L}^{u + u'} \qquad \text{and} \qquad (\mathcal{L}^u)_{\alice \alice'} \approx_\delta (\mathcal{O}^u)_\alice \,.
		\]
		Furthermore, the observable $\mathcal{L}^u = \Id$ when $u = 0$.
	\end{theorem}

		We now give the proof of Lemma~\ref{lem:qld-4-10}.

\begin{proof}[Proof of Lemma~\ref{lem:qld-4-10}]
For convenience in the proof we slightly abuse the notation $\approx_\delta$ to mean $\approx_{\poly(\eps)}$ for some polynomial function $\delta=\poly(\eps)$ that may differ each time the notation is used. 

\textbf{First step: construction of projective binary measurements $\{ \hat{R}^\omega_{a,b} \}$.}
	For every $\omega = (x,z,r,s)$ and $a,b \in \F_2$, define a measurement operator
	\[
		\hat{R}^\omega_{a,b} = \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a} \cdot \hat{M}^{(\Point,\zpt),z,s}_{b} \,.
	\]
	It is clear that $\{ \hat{R}^\omega_{a,b} \}_{a,b\in\F_2}$ is a POVM. Observe that on average over uniformly random $\omega$, 
	\begin{align}
	\label{eq:qld-r-2}
	\hat{R}^\omega_{a,b} \approx_{\sqrt{\delta_{\acom}}} \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a}\;,
	\end{align}
	which follows from the approximate commutation relation of Lemma~\ref{lem:qld-comm-cons} and the projectivity of $\{ \hat{M}^{(\Point,\zpt),z,s}_{b} \}$, together with Fact~\ref{fact:add-a-proj}. Next we show that $\{ \hat{R}^\omega_{a,b} \}$ is approximately self-consistent:  we aim to show that on average over $\omega$, it holds that $(\hat{R}^\omega_{a,b})_{\alice \alice'} \simeq_\delta (\hat{R}^\omega_{a,b})_{\bob \alice''}$ for some polynomial function $\delta = \poly(\eps)$. To show this, we perform the following calculation: (recall the state $\ket{\hat{\psi}}$ defined in~\eqref{eq:def-psihat})
	\begin{align}
		&\E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{R}^\omega_{a,b})_{\alice \alice'} \otimes (\hat{R}^\omega_{a,b})_{\bob \alice''} \ket{\hat{\psi}} \notag \\
		&\approx_{\delta_{\acom}^{1/4}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{R}^\omega_{a,b})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-1} \\
		&\approx_{\delta_{\acom}^{1/4}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-2} \\		
		&\approx_{\sqrt{\eps}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-3} \\
		&= \E_\omega \sum_{b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\bob \alice''} \ket{\hat{\psi}} \notag \\
		&\approx_{\eps} \E_\omega \sum_{b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-4} \\
		&= 1\;. \notag
	\end{align}
   	The approximation in~\eqref{eq:qld-rw-self-cons-1} is derived by bounding the magnitude of the difference:
	\begin{align*}
		&\left | \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{R}^\omega_{a,b} - \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{R}^\omega_{a,b})_{\bob \alice''} \ket{\hat{\psi}} \right | \\
		&\leq \sqrt{\E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{R}^\omega_{a,b} - \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'}^2 \ket{\hat{\psi}} } \cdot \sqrt{\E_\omega \sum_{a,b} \bra{\psi} (\hat{R}^\omega_{a,b})^2_{\bob \alice''} \ket{\psi} } \\
		&\leq \sqrt{\delta_{\acom}^{1/2}} \cdot \sqrt{1}\;,
	\end{align*}
	where the second line follows from Cauchy-Schwarz, and the third line follows from~\eqref{eq:qld-r-2} and the fact that $\sum_{a,b} (\hat{R}^\omega_{a,b})^2 \leq \Id$. The approximation in~\eqref{eq:qld-rw-self-cons-2} follows from a similar calculation. 
	The approximation in~\eqref{eq:qld-rw-self-cons-3} is derived by bounding the magnitude of the difference:
	\begin{align}
		&\left | \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot (\Id - \hat{M}^{(\Point,\xpt),x,r}_{a}))_{\alice \alice'}  \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}} \right | \notag \\
		&= \left | \E_\omega  \bra{\hat{\psi}} \Big(\sum_b \hat{M}^{(\Point,\zpt),z,s}_{b} \otimes \hat{M}^{(\Point,\zpt),z,s}_{b}\Big) \cdot \Big(\sum_{a} (\Id - \hat{M}^{(\Point,\xpt),x,r}_{a}) \otimes \hat{M}^{(\Point,\xpt),x,r}_{a} \Big) \ket{\hat{\psi}} \right | \\
		&\leq \sqrt{\E_\omega \sum_{a} \bra{\hat{\psi}} (\Id - \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'}^2 \otimes (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''}^2 \ket{\hat{\psi}}} \label{eq:qld-rw-self-cons-3-1}\\
                &= \sqrt{\E_\omega \sum_{a} \bra{\hat{\psi}} (\Id - \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}}} \label{eq:qld-rw-self-cons-3-2}\\
                &= \sqrt{ 1 - \E_{\omega} \sum_a \bra{\hat{\psi}} (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \ot  (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}}} \label{eq:qld-rw-self-cons-3-3}\\
                &=\sqrt{ \frac{1}{2} \E_{\omega} \sum_a \bra{\hat{\psi}} ( (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \ot I_{\bob \alice''} - I_{\alice \alice'} \ot  (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''})^2 \ket{\hat{\psi}}} \label{eq:qld-rw-self-cons-3-4}\\
		&\leq \sqrt{\eps}\;. \label{eq:qld-rw-self-cons-3-5}
	\end{align}
	Here \Cref{eq:qld-rw-self-cons-3-1} follows from the Cauchy-Schwarz inequality, the projectivity of $\hat{M}^{(\Point,\xpt),x,r}_{a}$, and the fact that $\sum_b \hat{M}^{(\Point,\zpt),z,s}_{b} \otimes \hat{M}^{(\Point,\zpt),z,s}_{b} \leq \Id$. \Cref{eq:qld-rw-self-cons-3-2,eq:qld-rw-self-cons-3-3,eq:qld-rw-self-cons-3-4} follow from projectivity and completeness of $\hat{M}^{(\Point, \xpt), x, r}_{a}$. \Cref{eq:qld-rw-self-cons-3-5} follows from the self-consistency of $\hat{M}^{(\Point,\xpt),x,r}_{a}$, established in \Cref{lem:qld-comm-cons}. 

        The approximation in~\eqref{eq:qld-rw-self-cons-4} follows from the self-consistency of $\hat{M}^{(\Point, \xpt), x, r}_a$, again from \Cref{lem:qld-comm-cons}, together with projectivity and \Cref{fact:agreement}.



	This shows that $(\hat{R}^\omega_{a,b})_{\alice \alice'} \simeq_\delta (\hat{R}^\omega_{a,b})_{\bob \alice''}$, as desired. Combined with \Cref{fact:agreement}, we have
	\begin{equation}
		\label{eq:rw-sc}
		(\hat{R}^\omega_{a,b})_{\alice \alice'} \approx_\delta (\hat{R}^\omega_{a,b})_{\bob \alice''}\;.
	\end{equation}


		Finally we apply the orthonormalization Lemma (Lemma~\ref{lem:ortho}) to $\{ \hat{R}^\omega_{a,b} \}$ in order to obtain projective measurements $\{ \hat{L}^\omega_{a,b} \}$ such that on average over $\omega$,
	\begin{equation}\label{eq:rl-close}
		\hat{L}^\omega_{a,b} \approx_{\delta} \hat{R}^\omega_{a,b}\;.
	\end{equation}

	\textbf{Second step: approximate linearity relations for $\{ \hat{R}^\omega_{a,b} \}$.}
	We proceed in three steps. First we establish linearity relations for $\{ \hat{M}^{(\Point,W),u,r}_b \}$. For all $W \in \{X,Z\}$, $u \in \F_q^m$, $r, r' \in \F_q$ and $c \in \F_2$, 
	\begin{align}
		\sum_{\substack{b,b' \in \F_2 : \\ b + b' = c }} \hat{M}^{(\Point,W),u,r}_b \, \hat{M}^{(\Point,W),u,r'}_{b'} &= \sum_{\substack{a,a' \in \F_q: \\ \tr(ar + a'r') = c}} \hat{M}^{(\Point,W),u}_a \cdot \hat{M}^{(\Point,W),u}_{a'} \notag\\
		&= \sum_{a : \tr(a (r +r')) = c } \hat{M}^{(\Point,W),u}_a \notag\\
		&= \hat{M}^{(\Point,W),u,r+r'}_c\;,\label{eq:m-lin}
	\end{align}
	where the second line follows from projectivity of $\{\hat{M}^{(\Point,W),u}_a\}$. 

	Second we show approximate linearity of the $\{ \hat{R}^\omega_{a,b} \}$. On average over $x,z \in \F_q^m$ and $r,r',s,s' \in \F_q$, 
	\begin{align}
	& \sum_{\substack{a,b,a',b' : \\ a + a' = c \\ b + b' = d}} \Big (\hat{R}^{x,z,r,s}_{a,b} \cdot \hat{R}^{x,z,r',s'}_{a',b'} \Big)_{\alice \alice'} \notag\\
	&\approx_\delta \sum_{\substack{a,b,a',b' : \\ a + a' = c \\ b + b' = d}} \Big( \hat{R}^{x,z,r,s}_{a,b} \Big)_{\alice \alice'} \otimes \Big( \hat{R}^{x,z,r',s'}_{a',b'} \Big)_{\bob \alice''} \label{eq:qld-r-52} \\
		&\approx_\delta \sum_{\substack{a,b,a',b': \\ a + a' = c \\ b + b' = d}} \Big( \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a}
 \Big)_{\alice \alice'} \otimes \Big(\hat{M}^{(\Point,\zpt),z,s'}_{b'} \cdot \hat{M}^{(\Point,\xpt),x,r'}_{a'} \Big)_{\bob \alice''} \label{eq:qld-r-53} \\
 	&\approx_\delta \sum_{\substack{b,b': \\ b + b' = d}} \Big( \hat{M}^{(\Point,\zpt),z,s}_{b}
 \Big)_{\alice \alice'} \otimes \Big(\hat{M}^{(\Point,\zpt),z,s'}_{b'} \cdot \hat{M}^{(\Point,\xpt),x,r+r'}_{c} \Big)_{\bob \alice''} \label{eq:qld-r-54} \\
 &\approx_\delta \sum_{\substack{b,b' : \\ b + b' = d}} \Big( \hat{M}^{(\Point,\zpt),z,s}_{b}
 \Big)_{\alice \alice'} \otimes \Big(\hat{M}^{(\Point,\xpt),x,r+r'}_{c} \cdot \hat{M}^{(\Point,\zpt),z,s'}_{b'}  \Big)_{\bob \alice''} \;.\label{eq:qld-r-55}
 \end{align}
	In each approximation, the answer summation is over $c,d \in \F_2$. Each approximation follows by applying a previously derived approximation to part of the expression, together with \Cref{fact:add-a-proj}.\anote{Eventual TODO: split up all these steps} Specifically, line~\eqref{eq:qld-r-52} uses the self-consistency of $\{ \hat{R}^\omega_{a,b} \}$ shown in~\eqref{eq:rw-sc}. Line~\eqref{eq:qld-r-53} follows from using~\eqref{eq:qld-r-2} twice. Line~\eqref{eq:qld-r-54} follows from the self-consistency and linearity properties of $\{ \hat{M}^{(\Point,X),x,r}_a \}$ shown in Lemma~\ref{lem:qld-comm-cons} and~\eqref{eq:m-lin} respectively. Line~\eqref{eq:qld-r-55} follows from the approximate commutativity relation shown in Lemma~\ref{lem:qld-comm-cons}.  Continuing,
 \begin{align}
\text{\eqref{eq:qld-r-55}} &\approx_\delta \Big(\hat{M}^{(\Point,\xpt),x,r+r'}_{c} \cdot \hat{M}^{(\Point,\zpt),z,s+s'}_{d}  \Big)_{\bob \alice''} \label{eq:qld-r-56} \\
 &\approx_\delta \Big ( \hat{R}^{x,z,r+r',s+s'}_{c,d} \Big)_{\bob \alice''} \label{eq:qld-r-57} \\
 &\approx_\delta \Big ( \hat{R}^{x,z,r+r',s+s'}_{c,d} \Big)_{\alice \alice'} \label{eq:qld-r-58}.
	\end{align}	
Line~\eqref{eq:qld-r-56} follows from self-consistency and linearity properties of $\{ \hat{M}^{(\Point,Z),z,s}_b \}$. Line~\eqref{eq:qld-r-57} follows from~\eqref{eq:qld-r-2} and \Cref{lem:qld-comm-cons}, and line~\eqref{eq:qld-r-58} follows from the self-consistency of $\{ \hat{R}^\omega_{a,b} \}$ from Eq.~\eqref{eq:rw-sc}. 

Third we deduce approximate linearity of the $\{ \hat{L}^\omega_{a,b} \}$. On average over $x,z \in \F_q^m$, and $r,r',s,s' \in \F_q$, we have
	\begin{align}
	\sum_{\substack{a,b,a',b': \\ a + a' = c \\ b + b' = d}}  \Big ( \hat{L}^{x,z,r,s}_{a,b} \, \hat{L}^{x,z,r',s'}_{a',b'} \Big)_{\alice \alice'} &\approx_\delta  \sum_{\substack{a,b,a',b': \\ a + a' = c \\ b + b' = d}} \Big( \hat{L}^{x,z,r,s}_{a,b} \Big)_{\alice \alice'} \otimes \Big (\hat{L}^{x,z,r',s'}_{a',b'} \Big)_{\bob \alice''}\notag \\
		&\approx_\delta  \sum_{\substack{a,b,a',b' : \\ a + a' = c \\ b + b' = d}}  \Big( \hat{R}^{x,z,r,s}_{a,b} \Big)_{\alice \alice'} \otimes \Big( \hat{R}^{x,z,r',s'}_{a',b'} \Big)_{\bob \alice''} \notag\\
		&\approx_\delta \Big ( \hat{R}^{x,z,r+r',s+s'}_{c,d} \Big)_{\alice \alice'} \notag\\
		&\approx_\delta \Big ( \hat{L}^{x,z,r+r',s+s'}_{c,d} \Big)_{\alice \alice'}\;.\label{eq:l-al}
	\end{align}
	The first two approximations follow from the closeness of the $\{ \hat{R}^\omega_{a,b} \}$ and $\{ \hat{L}^\omega_{a,b} \}$  guaranteed by~\eqref{eq:rl-close} as well as the self-consistency of $\{ \hat{R}^\omega_{a,b} \}$ shown in~\eqref{eq:rw-sc}. The third approximation follows from the linearity properties of $\{ \hat{R}^\omega_{a,b} \}$ in~\eqref{eq:qld-r-55}. 

	\textbf{Third step: construction of $\{ \hat{Q}^{x,z}_{a,b} \}$.}
	For each $\omega$ define an observable $\mathcal{O}^\omega = \sum_{a,b \in \F_2} (-1)^{a+ b} \hat{L}^\omega_{a,b}$.  The self-consistency of $\mathcal{O}^\omega$ between registers $\alice \alice'$ and $\bob \alice''$ follows from the self-consistency of the $\{ \hat{L}^\omega_{a,b} \}$, which is obtained by combining~\eqref{eq:rw-sc} and~\eqref{eq:rl-close}. We now verify approximate linearity. On average over $x,z \in \F_q^m$, and $r,r',s,s' \in \F_q$, 
	\begin{align*}
		\mathcal{O}^{x,z,r,s} \, \mathcal{O}^{x,z,r',s'} &= \sum_{a,b,a',b'} (-1)^{a + b + a' + b'} \hat{L}^{x,z,r,s}_{a,b} \, \hat{L}^{x,z,r',s'}_{a',b'} \\
		&\approx_\delta \sum_{c,c'} (-1)^{c+c'} \hat{L}^{x,z,r+r',s+s'}_{c,c'} \\
		&= \mathcal{O}^{x,z,r+r',s+s'}\,
	\end{align*}
	where the approximation follows from the approximate linearity properties of $\{ \hat{L}^\omega_{a,b} \}$ shown in~\eqref{eq:l-al}.
	Identify the field $\F_q$ with the vector space $\F_2^t$, and thus we treat pairs $(r,s)$ as vectors in $\F_2^{2t}$. For every $x,z \in \F_q^m$, we can apply Theorem~\ref{thm:linearity} to the collection of observables $\{ \mathcal{O}^{x,z,r,s} \}_{r,s \in \F_q}$ to obtain the existence of ``{exactly linear}'' observables $\{ \mathcal{L}^{x,z,r,s} \}$ that are $\delta$-close to $\{ \mathcal{O}^{x,z,r,s} \}$, on average over the choice of $x,z,r,s$. By assuming that $\ket{\hat{\psi}}$ has sufficiently many ancilla zero qubits, we do not need to extend the state further. 

	We are ready to define the measurements $\{\hat{Q}^{x,z}_{a,b} \}$ whose existence is claimed in the statement of the lemma. For all $x,z\in \F_q^m$ and $a,b \in \F_q$, define
	\[
		\hat{Q}^{x,z}_{a,b} = \E_{r,s} (-1)^{\tr(ra + sb)} \mathcal{L}^{x,z,r,s}\;.
	\]
	This operator is a projection (and thus positive semidefinite):
	\begin{align*}
	(\hat{Q}^{x,z}_{a,b})^2 &= \E_{r,s,r',s'} (-1)^{\tr((r+r')a + (s+s')b)} \mathcal{L}^{x,z,r,s} \, \mathcal{L}^{x,z,r',s'}\\ 
	&= \E_{r,s,r',s'} (-1)^{\tr((r+r')a + (s+s')b)} \mathcal{L}^{x,z,r+r',s+s'} \\
	&= \E_{r,s} (-1)^{\tr(ra + sb)}  \mathcal{L}^{x,z,r,s}\;.
	\end{align*}
	The second equality follows from the exact linearity of the $\{ \mathcal{L}^{x,z,r,s} \}$. Next, the operators sum to identity:
	\begin{align*}
		\sum_{a,b} \hat{Q}^{x,z}_{a,b} &= \E_{r,s} \sum_{a,b} (-1)^{\tr(ra + sb)} \mathcal{L}^{x,z,r,s} \\
		&= \mathcal{L}^{x,z,0,0} \\
		&= \Id\;.
	\end{align*}
	Thus $\{\hat{Q}^{x,z}_{a,b}\}$ forms a projective measurement.

\end{definition}

\begin{remark}[Diagonal questions with zero direction]\label{rem:ld-win-zero-direction}
	The source states the two line-versus-point clauses with ``the'' $t \in \F_q$ such that $x_{\overline w} = u_0 + t v$. When the direction is nonzero and $x_{\overline w}$ lies on the line, exactly one such $t$ exists and the formulation above agrees with the source. But zero directions occur: Definition~\ref{def:line} explicitly permits them, and the question distribution of Definition~\ref{def:ld-question-distribution} produces $\mathsf{DLine}$ questions with $v' = \pi_{i-1}(v) = 0$ with positive probability, namely whenever the last $m - i + 1$ coordinates of $v$ vanish. In that case $\ell(u_0, 0) = \{u_0\}$, every $t \in \F_q$ satisfies $x_{\overline w} = u_0 + t v'$ when $x_{\overline w} = u_0$, and the source clause does not determine acceptance for a nonconstant answer polynomial. The universal quantification over $t$ adopted in Definition~\ref{def:ld-win-predicate} makes the predicate a well-defined function of its arguments; it accepts vacuously when no such $t$ exists, a case the question distribution never produces. Completeness is unaffected: the restriction of a polynomial $g$ to the singleton line $\ell(u_0,0)$, expressed through the parameterization $t \mapsto u_0 + t \cdot 0$, is the constant polynomial with value $g(u_0)$, which passes the check for every $t$. Soundness is likewise unaffected: zero directions occur with probability at most $2/(mq)$, and the proof of Theorem~\ref{lem:ld-soundness} shows that any acceptance convention on this event changes success probabilities by at most that amount, which is absorbed into the universal constants of $\delta_{\mathrm{ld}}$.
\end{remark}

The soundness properties of the low individual degree game are expressed in terms of the following class of measurements.

\begin{definition}[Low-degree polynomial measurements]\label{def:ld-meas}
	\uses{def:polyfunc, def:polymeasurements, def:polynomials-degree}
	Let $\polymeas{m}{q}{d}$ denote the set of POVM measurements indexed by $\polyfunc{m}{q}{d}$, the polynomial representatives of individual degree at most $d$ in each variable; this is the notion of Definition~\ref{def:polymeasurements}, and the argument order $(m,q,d)$ follows that definition (the paper orders the arguments as $(m,d,q)$). By Definition~\ref{def:polynomials-degree}, evaluation identifies these representatives with the corresponding polynomial functions $g\colon \F_q^m \to \F_q$, bijectively whenever $d \le q-1$; the parameter regimes of this chapter (Definition~\ref{def:introparams} fixes $d = 1$, and admissibility gives $q \ge 2$) always satisfy this. More generally, for an integer $k$ and tuples $m = (m_1,\ldots,m_k)$, $q = (q_1,\ldots,q_k)$, $d = (d_1,\ldots,d_k)$, let $\mathrm{PolyMeas}(m,q,d,k)$ denote the set of measurements $G = \{G_{g_1,\ldots,g_k}\}$ such that for each $i \in \{1,\ldots,k\}$, the outcome index $g_i$ is a polynomial $g_i\colon \F_{q_i}^{m_i} \to \F_{q_i}$ of individual degree at most $d_i$.
\end{definition}

Quantum soundness of a version of the classical low-degree test for polynomials of low \emph{total} degree was claimed by Natarajan and Vidick, building on an analysis of a three-prover version of the test by Vidick; there is a known gap in the soundness analysis of that test, and it is not used here. Instead, the construction relies on the low \emph{individual} degree test, whose quantum soundness is proved in~\cite{Ji2020LowIndividualDegree} and generalized in~\cite{Ji2021Quantum}. The statement below is the form most directly useful in what follows.

% The paper states this result in a theorem environment with the label lem:ld-soundness.
% We keep both the environment and the label verbatim for cross-reference fidelity.
\begin{theorem}[Quantum soundness of the simultaneous classical low individual degree test]\label{lem:ld-soundness}
	\uses{def:ld-game, def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:projective-strategy-general, def:tensor-product-value, def:povm-distance, def:bracket}
	There exists a function
	\[
		\delta_{\mathrm{ld}}(\eps, q, m, d, k) = a\,(dmk)^a \bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)
	\]
	for universal constants $a \ge 1$ and $0 < b \le 1$ such that the following holds. For all $\eps > 0$ and every parameter tuple $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game} (so $m, d, k \ge 1$, $q$ is an admissible field size, and $m$ divides $q$), and for all projective strategies $(\psi, A, B)$ that succeed with probability at least $1-\eps$ in the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$, there exist measurements
	\[
		G^w \in \mathrm{PolyMeas}(m,q,d,k)
	\]
	on $\hilb_w$ for $w \in \{\mathrm A,\mathrm B\}$, where by slight abuse of notation $m$, $q$, $d$ denote the constant tuples $(m,\ldots,m)$, $(q,\ldots,q)$, $(d,\ldots,d)$ of length $k$, such that
	\begin{align*}
		A^{\mathsf{Point},\, u}_{a_1,\ldots,a_k} \ot I_{\mathrm B}
		&\approx_{\delta_{\mathrm{ld}}}
		I_{\mathrm A} \ot G^{\mathrm B}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]}\;,\\
		G^{\mathrm A}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]} \ot I_{\mathrm B}
		&\approx_{\delta_{\mathrm{ld}}}
		I_{\mathrm A} \ot B^{\mathsf{Point},\, u}_{a_1,\ldots,a_k}\;,\\
		G^{\mathrm A}_{g_1,\ldots,g_k} \ot I_{\mathrm B}
		&\approx_{\delta_{\mathrm{ld}}}
		I_{\mathrm A} \ot G^{\mathrm B}_{g_1,\ldots,g_k}\;,
	\end{align*}
	where $\delta_{\mathrm{ld}} = \delta_{\mathrm{ld}}(\eps,q,m,d,k)$, all three approximations are with respect to the state $\ket{\psi}$, and the bracket notation for post-processed outcomes is that of Definition~\ref{def:bracket}. The first two approximations hold on average over the uniform distribution on $u \in \F_q^m$; no question distribution is associated with the third.
\end{theorem}
\begin{proof}
	\uses{def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:povm-distance}
	Let $\Sigma = \F_q$ and let $\code \subseteq \Sigma^q$ be the Reed--Solomon code of degree $d$: the set of all $(p(x_1),\ldots,p(x_q))$ where $p\colon \F_q \to \F_q$ is a univariate polynomial of degree at most $d$ and $x_1,\ldots,x_q$ enumerate $\F_q$. We may assume $d < q$. In the opposite regime the statement is immediate: for $d \ge q$ the prefactor gives $\delta_{\mathrm{ld}} \ge a\,(dmk)^a\, q^{-b} \ge q^{a-b} \ge 1$, using $m, k \ge 1$, while the quantity bounded in Definition~\ref{def:povm-distance} never exceeds $2$ for families of POVM elements, so the three approximations hold for an arbitrary choice of $G^w \in \mathrm{PolyMeas}(m,q,d,k)$. For $d < q$, evaluation is injective on polynomials of degree at most $d$ and a nonzero polynomial of degree at most $d$ vanishes at no more than $d$ of the $q$ points, so $\code$ is a linear $[q,\, d+1,\, q-d]_\Sigma$ code.
	% The paper prints the parameters as [q, d+1, n-d+1] with an undefined n. With the
	% intended value n = q the printed distance q-d+1 exceeds the true minimum distance
	% q-d of the degree-d evaluation code, and the dimension claim d+1 requires d < q.
	% Both points are corrected above; the regime d >= q, which the parameter tuple of
	% Definition def:ld-game permits, is handled by the triviality argument. The
	% boundary values d = 0 and k = 0 are excluded by the parameter domain of
	% Definition def:ld-game, following the source's convention that \N denotes
	% the positive integers.
	% The source asserts a flat identity between the two tests
	% (references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:446-454).
	% After the zero-direction correction of Definition def:ld-win-predicate
	% (see rem:ld-win-zero-direction) the identity holds only away from
	% zero-direction diagonal questions, so the import is scoped to the predicate
	% analyzed in the external source and bridged by the probability estimate below,
	% which is insensitive to the external test's acceptance convention on that event.
	The two-prover tensor-code test for the code $\code^{\ot m}$, as described in Figures~1 and~2 of~\cite{Ji2021Quantum}, agrees with the game $\mathfrak{G}^{\mathrm{ld}}$ with parameters $\mathsf{ldparams}$ and $k=1$ on every question pair whose diagonal-line direction is nonzero: the axis-parallel line-versus-point test is their axis-parallel lines test, with the roles of the two players chosen uniformly at random, which is consistent with the two-prover variant of the tensor-code test from Section~4.1 there; the diagonal line-versus-point test is their subcube commutation test, again with the added symmetrization between the players; and the consistency test is their synchronicity test. On diagonal line-versus-point questions with direction $v' = \pi_{i-1}(v) = 0$, the win predicate of Definition~\ref{def:ld-win-predicate} resolves an ambiguity of the source (Remark~\ref{rem:ld-win-zero-direction}), and the resolution is not required to match the acceptance convention of the subcube commutation test on this event: the event has probability at most $2/(mq)$ under the question distribution, since the direction $\pi_{i-1}(v)$ vanishes with probability $\frac1m \sum_{j=1}^m q^{-j} \le \frac{1}{m(q-1)} \le \frac{2}{mq}$ over uniform $(s,v)$, so the success probabilities of any fixed strategy in the two games differ by at most $2/(mq)$. A projective strategy that succeeds in $\mathfrak{G}^{\mathrm{ld}}$ with probability at least $1-\eps$ therefore succeeds in the tensor-code test with probability at least $1 - \eps - 2/(mq)$. Theorem~4.7 of~\cite{Ji2021Quantum}, instantiated with its internal parameter $k$ chosen as $m^3 d$ (this parameter is unrelated to the simultaneity parameter $k$ of $\mathsf{ldparams}$) and applied with the success deficit $\eps + 2/(mq)$ in place of $\eps$, then yields the present statement for $k = 1$: since $0 < b \le 1$ and $m \ge 1$ give $(\eps + 2/(mq))^b \le \eps^b + 2\,q^{-b}$, the additional error is absorbed into $\delta_{\mathrm{ld}}$ by enlarging the universal constant $a$, using $dmk \ge 1$. The case of general $k$ follows by a standard reduction, following exactly the derivation of Theorem~4.43 from Theorem~4.40 in~\cite{Natarajan2018NEEXP}. Quantum soundness of the low individual degree test itself is the result of~\cite{Ji2020LowIndividualDegree}; Remark~\ref{rem:ld-soundness-provider} relates the present statement to Theorem~\ref{thm:main-formal}, which proves that result.
\end{proof}

\begin{remark}[Relation to the low individual degree test of Chapter~\ref{chap:test}]\label{rem:ld-soundness-provider}
	Theorem~\ref{lem:ld-soundness} is imported: the proof above reduces it to Theorem~4.7 of~\cite{Ji2021Quantum}, instantiated with its internal parameter $k$ chosen as $m^3 d$, followed by the extension to simultaneous $k$-tuples of~\cite{Natarajan2018NEEXP}. The result of~\cite{Ji2020LowIndividualDegree} that underlies it is proved here as Theorem~\ref{thm:main-formal}: for every projective strategy passing the $(m,q,d)$ low individual degree test of Definition~\ref{def:low-individual-degree-test} with probability at least $1-\eps$, that theorem produces measurements in $\polymeas{m}{q}{d}$ satisfying consistency relations of the same shape as the three approximations of Theorem~\ref{lem:ld-soundness}. Theorem~\ref{lem:ld-soundness} is not a consequence of Theorem~\ref{thm:main-formal} alone: a derivation from it would require, in addition, an equivalence between the typed game $\mathfrak{G}^{\mathrm{ld}}_{(q,m,d,1)}$ and the $(m,q,d)$ test of Chapter~\ref{chap:test} --- matching the two question distributions, the two win conditions, and the two error functions --- together with the extension from $k = 1$ to general $k$ by the reduction of~\cite{Natarajan2018NEEXP} cited above. Neither implication is proved in this chapter, and the proof of Theorem~\ref{lem:ld-soundness} given above does not invoke Theorem~\ref{thm:main-formal}.
\end{remark}

\section{The Magic Square game}
% Paper label sec:ms kept for cross-reference fidelity.
\label{sec:ms}

We recall the Magic Square game of Mermin and Peres. It is a simple self-test for two EPR pairs, and it allows one to test that a pair of binary observables \emph{anticommutes}; both properties are used in the Pauli basis test. Here it is presented as a binary constraint satisfaction game. Throughout this section and the next, $\sigma^X$ and $\sigma^Z$ denote the single-qubit Pauli observables, with associated two-outcome projective measurements $\{\sigma^W_b\}_{b \in \F_2}$ for $W \in \{X,Z\}$.

\section{Generalized Pauli observables}
% Paper label sec:generalized-pauli kept for cross-reference fidelity.
\label{sec:generalized-pauli}

\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
	\uses{def:subfield-trace, def:lin-reg}
	Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
	observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
	\begin{equation}\label{eq:pauli-fp}
		\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
		\qquad \text{and} \qquad
		\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
	\end{equation}
	for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
	\emph{generalized Pauli observables over $\F_q$} are the unitaries on
	$\C^{\F_q}$
	\[
		\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
		\qquad \text{and} \qquad
		\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
	\]
	for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
	(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
	the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
	signs. All the $\tau^X$ operators commute with one another, as do all the
	$\tau^Z$ operators. Their common eigenbases consist of the vectors
	$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
	\[
		\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
		\omega^{-\tr(ej)} \ket{j}\;, \qquad
		\ket{e_Z} = \ket{e}\;;
	\]
	the Fourier transform
	\begin{equation}\label{eq:fourier-f}
		F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
		\omega^{-\tr(ab)} \ket{a}\bra{b}
	\end{equation}
	maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
	$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
	are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
	systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
	\[
		\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
		\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
	\]
	for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
\end{definition}

\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
	\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
	Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
	\begin{enumerate}
		\item For all $a, a' \in \F_q$ and $b \in \F_p$,
		      \begin{equation}\label{eq:pauli-product-power}
			      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
			      \qquad \text{and} \qquad
			      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
		      \end{equation}
		      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$, so each
		      $\tau^W(a)$ is a unitary with eigenvalues that are $p$-th roots
		      of unity.
		\item For all $a, b \in \F_q^n$,
		      % Paper equation label kept on the display it names.
		      \begin{equation}\label{eq:twisted-fq}
			      \tau^X(a)\, \tau^Z(b)
			      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
		      \end{equation}
		      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
		      $q = p$, $n = 1$ reads
		      \begin{equation}\label{eq:twisted-fp}
			      \sigma^X(a)\, \sigma^Z(b)
			      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
			      \qquad \text{for all } a, b \in \F_p\;.
		      \end{equation}
	\end{enumerate}
\end{lemma}
\begin{proof}
	\uses{def:generalized-pauli, def:subfield-trace}
	All identities are verified on computational basis states. For the product
	relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
	$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
	combine by $\F_q$-linearity of the trace, and the power relation follows by
	iterating. For the scalar twisted commutation,
	$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
	$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
	\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
	follows by applying the scalar relation factor by factor and summing the
	exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
	trace is the identity map, which gives \eqref{eq:twisted-fp}.
\end{proof}

\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
	\uses{def:dot-product-orthogonal, def:subfield-trace}
	Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
	$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
	$v \notin V^\perp$,
	\[
		\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
	\]
	where the expectation is over a uniformly random vector $\bu$ in $V$.
\end{lemma}
\begin{proof}
	This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
	the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
	on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
	shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
	for the expectation, translation invariance of the uniform distribution on
	$V$ gives
	$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
	= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
	forces $C = 0$.
\end{proof}

\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
	\uses{def:generalized-pauli, def:subfield-trace}
	For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
	% Paper equation label kept on the display it names.
	\begin{equation}\label{eq:pauli-obs-proj}
		\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
	\end{equation}
	and conversely
	\begin{equation}\label{eq:pauli-inversion-0}
		\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
		= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
		\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
		= \tau^W_b\;.
	\end{equation}
\end{lemma}
\begin{proof}
	\uses{def:generalized-pauli, lem:cancellation}
	Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
	$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
	definition, and for $W = X$ it follows from the single-qudit computation
	$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
	Expanding $\tau^W(a)$ in the orthonormal eigenbasis
	$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
	substitute the first display and exchange the order of summation; by
	Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
	$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
	it equals $1$.
\end{proof}

